URL, DB, USER, KEY = "https://erp.example.com", "mydb", "api@example.com", "API-KEY"   # API key: user preferences → Account Security
uid = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/common").authenticate(DB, USER, KEY, {})
m = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/object")
call = lambda model, method, *a, **kw: m.execute_kw(DB, uid, KEY, model, method, list(a), kw)

so = call("sale.order", "search_read", [["name", "=", "S00042"]],
          fields=["name", "state", "invoice_status", "picking_ids", "invoice_ids"])[0]
print(f"{so['name']}: order={so['state']}  invoicing={so['invoice_status']}")

for p in call("stock.picking", "read", so["picking_ids"], fields=["name", "state", "origin"]):
    print(f"  delivery {p['name']:<18} {p['state']:<10} origin={p['origin']}")

for inv in call("account.move", "read", so["invoice_ids"],
                fields=["name", "move_type", "state", "payment_state", "amount_residual"]):
    print(f"  {inv['move_type']:<11} {inv['name']:<18} {inv['state']:<7} {inv['payment_state']:<12} open {inv['amount_residual']:.2f}")

# S00042: order=sale  invoicing=invoiced
